// Написан вручную (три роли — генератор не умеет), не прогонялся — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/date-now.md 2.1 · кейс .qa/tests/date-now/DN-06.md
// Date Now включает только user2 (Premium). В finally: Date Now выкл., шаринг выкл. у всех, фильтры возвращены, сессии сохранены.
import { test, expect } from '../../fixtures';
import { enableSharing, disableSharing, openMap, userIdOf } from '../location-map/map-helpers';
import { saveSession } from '../_shared/session';
import { setupGeo, enableDateNow30, disableDateNow, pollNearby, findRow, widenAgePrefs, restoreAgePrefs, NAMES, type AgePrefs } from './date-now-helpers';

test.describe('דייט עכשיו — что видят другие', () => {
  test.describe.configure({ timeout: 300_000 }); // три роли + опрос карты у наблюдателя
  test('Наблюдатель видит Date Now выделенным и первым, хотя он дальше; после «לכבות» приоритет снят @iphone @data (#1fd43a)', async ({ asUser }) => {
    const user2 = await asUser('user2');
    const reg1 = await asUser('reg1');
    const reg4 = await asUser('reg4');
    await setupGeo(user2, 'user2');
    await setupGeo(reg1, 'reg1');
    await setupGeo(reg4, 'reg4');
    const user2Id = userIdOf('user2');
    const reg4Id = userIdOf('reg4');
    let prefsReg1: AgePrefs | undefined;
    let prefsUser2: AgePrefs | undefined;
    try {
      // 1. Предусловия: фильтры шире (user2 56 лет вне 21–35 у reg1), шаринг у всех троих
      prefsReg1 = await widenAgePrefs(reg1);
      prefsUser2 = await widenAgePrefs(user2);
      await enableSharing(reg4);
      await enableSharing(user2);
      await disableDateNow(user2);
      await enableSharing(reg1);

      // 2. reg1 видит обеих
      await pollNearby(reg1, (rows) => findRow(rows, user2Id).idx >= 0 && findRow(rows, reg4Id).idx >= 0, 'nearby_live reg1: user2 и reg4');

      // 3. user2 включает Date Now
      await openMap(user2);
      await enableDateNow30(user2);

      // 4. reg1: user2 date_now=true и стоит раньше ближней reg4 (AC 2, 3, 5, 6)
      const on = await pollNearby(reg1, (rows) => findRow(rows, user2Id).row?.date_now === true, 'nearby_live reg1: user2 date_now=true');
      const u = findRow(on, user2Id);
      const r = findRow(on, reg4Id);
      expect(r.row?.date_now, 'reg4 без Date Now').toBe(false);
      expect(Number(u.row?.distance_m), 'user2 дальше reg4').toBeGreaterThan(Number(r.row?.distance_m));
      expect(u.idx, 'Date Now первым (AC 5)').toBeLessThan(r.idx);
      // Карусель: в RTL первая карточка — правее
      const cardUser2 = reg1.getByText(new RegExp(NAMES.user2)).first();
      const cardReg4 = reg1.getByText(new RegExp(NAMES.reg4)).first();
      await expect(cardUser2).toBeVisible();
      await expect(cardReg4).toBeVisible();
      const [bu, br] = [await cardUser2.boundingBox(), await cardReg4.boundingBox()];
      expect(bu!.x, 'карточка user2 первой в карусели (правее в RTL)').toBeGreaterThan(br!.x);

      // 5. user2 «לכבות» → приоритет снят: reg4 снова раньше (AC 5, 8)
      await disableDateNow(user2);
      const off = await pollNearby(reg1, (rows) => findRow(rows, user2Id).row?.date_now === false, 'nearby_live reg1: user2 date_now=false');
      expect(findRow(off, reg4Id).idx, 'ближняя reg4 снова первой').toBeLessThan(findRow(off, user2Id).idx);
    } finally {
      await disableDateNow(user2).catch(() => {});
      for (const p of [user2, reg1, reg4]) await disableSharing(p).catch(() => {});
      await restoreAgePrefs(prefsReg1).catch(() => {});
      await restoreAgePrefs(prefsUser2).catch(() => {});
      await saveSession(user2, 'user2');
      await saveSession(reg1, 'reg1');
      await saveSession(reg4, 'reg4');
    }
  });
});
